  Looks up a localized string similar to function closeInvalid() {
  let divs = document.getElementsByTagName("div");
  for (div of divs) {
    if (div.getAttribute("data-animate-modal-popup") == "true") {
      let subdivs = div.getElementsByTagName("div");
      for (let subdiv of subdivs) {

        subdiv.click();

      }

    }
  }
} closeInvalid().

  Looks up a localized string similar to function InitiateMessage(num,message){
    var senderLink = document.getElementById("senderLink");
    senderLink.setAttribute("href",`https://api.whatsapp.com/send?phone=${num}&text=${message}`);
    senderLink.click();

}InitiateMessage("{{NUM}}","{{MESSAGE}}");.

  Looks up a localized string similar to function InitiateSender(){
    var app =document.getElementsByTagName("header")[0];
    var a=document.createElement("a");
    a.id="senderLink";
    app.appendChild(a);
}InitiateSender();.

  Looks up a localized string similar to function isInvalid() {
  let divs = document.getElementsByTagName("div");
  for (div of divs) {
    if (div.getAttribute("data-animate-modal-popup") == "true") {
      return true;
    }
  }
  return false;
} return isInvalid();.

